using System;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;
public static class FitAttack01Tail
{
 static Transform Bone(GameObject r,string n)=>r.GetComponentsInChildren<Transform>().First(t=>t.name==n);
 static Vector3 Grip(SkinnedMeshRenderer s,string side){var m=s.sharedMesh;int h=Array.FindIndex(s.bones,b=>b.name==side+"Hand"),e=Array.FindIndex(s.bones,b=>b.name==side+"LowerArm");Vector3 axis=((Vector3)m.bindposes[h].inverse.GetColumn(3)-(Vector3)m.bindposes[e].inverse.GetColumn(3)).normalized;return m.bindposes[h].MultiplyVector(axis*.095f-Vector3.ProjectOnPlane(Vector3.up,axis).normalized*.025f);}
 static void IK(Transform upper,Transform lower,Transform hand,Vector3 target)
 {
  var origin=upper.position;float l1=Vector3.Distance(origin,lower.position),l2=Vector3.Distance(lower.position,hand.position);var dir=(target-origin).normalized;float d=Mathf.Clamp(Vector3.Distance(origin,target),Mathf.Abs(l1-l2)+.0001f,l1+l2-.0001f);
  var pole=Vector3.ProjectOnPlane(lower.position-origin,dir).normalized;if(pole.sqrMagnitude<.1f)pole=Vector3.ProjectOnPlane(upper.right,dir).normalized;
  float x=(l1*l1-l2*l2+d*d)/(2*d);Vector3 elbow=origin+dir*x+pole*Mathf.Sqrt(Mathf.Max(0,l1*l1-x*x));
  upper.rotation=Quaternion.FromToRotation(lower.position-origin,elbow-origin)*upper.rotation;
  lower.rotation=Quaternion.FromToRotation(hand.position-lower.position,origin+dir*d-lower.position)*lower.rotation;
 }
 static Mesh Fist(SkinnedMeshRenderer s)
 {
  var mesh=UnityEngine.Object.Instantiate(s.sharedMesh);mesh.name="AttackBody_BothFists";int h=Array.FindIndex(s.bones,b=>b.name=="LeftHand"),e=Array.FindIndex(s.bones,b=>b.name=="LeftLowerArm");var bind=mesh.bindposes;Vector3 wrist=bind[h].inverse.GetColumn(3),elbow=bind[e].inverse.GetColumn(3),axis=(wrist-elbow).normalized,up=Vector3.ProjectOnPlane(Vector3.up,axis).normalized;var v=mesh.vertices;var weights=mesh.boneWeights;
  Func<int,float> influence=i=>{var w=weights[i];return(w.boneIndex0==h?w.weight0:0)+(w.boneIndex1==h?w.weight1:0)+(w.boneIndex2==h?w.weight2:0)+(w.boneIndex3==h?w.weight3:0);};float length=Enumerable.Range(0,v.Length).Where(i=>influence(i)>.5f).Max(i=>Vector3.Dot(v[i]-wrist,axis));float start=length*.32f,angle=155*Mathf.Deg2Rad,radius=(length-start)/angle;
  for(int i=0;i<v.Length;i++){float distance=Vector3.Dot(v[i]-wrist,axis);if(influence(i)<.4f||distance<=start)continue;float theta=Mathf.Clamp01((distance-start)/(length-start))*angle;var side=v[i]-wrist-axis*distance;float thickness=Vector3.Dot(side,up);side-=up*thickness;v[i]=wrist+axis*(start+(radius+thickness)*Mathf.Sin(theta))+up*((radius+thickness)*Mathf.Cos(theta)-radius)+side;}
  mesh.vertices=v;mesh.RecalculateNormals();mesh.RecalculateBounds();return mesh;
 }
 public static object Verify()
 {
  var reports=new List<object>();foreach(var live in GameObject.Find("New Knight Attack Previews").GetComponentsInChildren<Animator>().Where(a=>a.transform.parent.name=="Attack 01 - Attack")){var root=UnityEngine.Object.Instantiate(live.transform.parent.gameObject);try{var a=root.GetComponentInChildren<Animator>();a.enabled=false;var clip=a.runtimeAnimatorController.animationClips[0];var source=AssetDatabase.LoadAssetAtPath<AnimationClip>("Assets/3DBattle/NewPlayer/Attack/Previews/BeforeHandFit/"+System.IO.Path.GetFileName(AssetDatabase.GetAssetPath(clip)));var lh=Bone(root,"LeftHand");var rh=Bone(root,"RightHand");var sword=Bone(root,"Sword");float freePosition=0,freeAngle=0,swordAngle=0;int free=0;for(int i=0;i<=240;i++){float time=clip.length*i/240;source.SampleAnimation(a.gameObject,time);bool released=Vector3.Distance(lh.position,rh.position)>=.55f;var p=lh.position;var q=lh.rotation;var sq=sword.rotation;clip.SampleAnimation(a.gameObject,time);swordAngle=Mathf.Max(swordAngle,Quaternion.Angle(sq,sword.rotation));if(released){free++;freePosition=Mathf.Max(freePosition,Vector3.Distance(p,lh.position));freeAngle=Mathf.Max(freeAngle,Quaternion.Angle(q,lh.rotation));}}reports.Add(new{name=live.transform.parent.name,freeSamples=free,freeHandPositionError=freePosition,freeHandAngleError=freeAngle,swordAngleError=swordAngle});}finally{UnityEngine.Object.DestroyImmediate(root);}}return reports;
 }
 public static object Run()
 {
  if(Application.isPlaying)throw new Exception("Stop play first");const string folder="Assets/3DBattle/NewPlayer/Attack/Previews";string backupFolder=folder+"/BeforeAttack01TailFit_20261103";if(!AssetDatabase.IsValidFolder(backupFolder))AssetDatabase.CreateFolder(folder,"BeforeAttack01TailFit_20261103");
  var reference=UnityEngine.Object.Instantiate(GameObject.Find("Running Knight Preview"));var ra=reference.GetComponentInChildren<Animator>();ra.enabled=false;ra.runtimeAnimatorController.animationClips[0].SampleAnimation(ra.gameObject,0);var refSword=Bone(reference,"Sword");Quaternion mountRotation=refSword.localRotation;Vector3 mountPosition=refSword.localPosition;UnityEngine.Object.DestroyImmediate(reference);
  var liveAnimators=GameObject.Find("New Knight Attack Previews").GetComponentsInChildren<Animator>().Where(a=>a.transform.parent.name=="Attack 01 - Attack").ToArray();
  var firstSkin=liveAnimators[0].GetComponentInChildren<SkinnedMeshRenderer>();string meshPath=folder+"/AttackBody_BothFists.asset";var fist=AssetDatabase.LoadAssetAtPath<Mesh>(meshPath);if(fist==null){fist=Fist(firstSkin);AssetDatabase.CreateAsset(fist,meshPath);}
  var reports=new List<object>();
  foreach(var liveA in liveAnimators){var clip=liveA.runtimeAnimatorController.animationClips[0];string path=AssetDatabase.GetAssetPath(clip),backup=backupFolder+"/"+System.IO.Path.GetFileName(path);if(AssetDatabase.LoadAssetAtPath<AnimationClip>(backup)==null)AssetDatabase.CopyAsset(path,backup);var source=AssetDatabase.LoadAssetAtPath<AnimationClip>(backup);
   var root=UnityEngine.Object.Instantiate(liveA.transform.parent.gameObject);root.transform.SetPositionAndRotation(Vector3.zero,Quaternion.identity);var a=root.GetComponentInChildren<Animator>();a.enabled=false;
   try{
    var skin=root.GetComponentInChildren<SkinnedMeshRenderer>();var rh=Bone(root,"RightHand");var lh=Bone(root,"LeftHand");var ru=Bone(root,"RightUpperArm");var rl=Bone(root,"RightLowerArm");var lu=Bone(root,"LeftUpperArm");var ll=Bone(root,"LeftLowerArm");var sword=Bone(root,"Sword");var rg=Grip(skin,"Right");var lg=Grip(skin,"Left");
    var rb=(skin.transform.localToWorldMatrix*skin.sharedMesh.bindposes[Array.IndexOf(skin.bones,rh)].inverse).rotation;var lb=(skin.transform.localToWorldMatrix*skin.sharedMesh.bindposes[Array.IndexOf(skin.bones,lh)].inverse).rotation;
    var changed=liveA.transform.parent.name.StartsWith("Attack 01")||liveA.transform.parent.name.StartsWith("Attack 06")?new[]{ru,rl,rh,lu,ll,lh,sword}:new[]{ru,rl,rh,sword};var records=changed.ToDictionary(t=>t,t=>Enumerable.Range(0,7).Select(_=>new List<Keyframe>()).ToArray());int frames=Mathf.RoundToInt(source.length*480);float maxPositionShift=0,maxLeftError=0;int held=0;var desired=new List<Quaternion>();var weights=new List<float>();
    for(int f=0;f<=frames;f++){float time=source.length*f/frames;source.SampleAnimation(a.gameObject,time);float distance=Vector3.Distance(rh.position,lh.position);float weight=1-Mathf.SmoothStep(0,1,Mathf.InverseLerp(.38f,.55f,distance));weights.Add(weight);var originalSwordPosition=sword.position;var desiredRotation=sword.rotation;desired.Add(desiredRotation);var leftRot=lh.rotation;var leftUpper=lu.localRotation;var leftLower=ll.localRotation;
     if(time>51f/30f){Quaternion handRotation=desiredRotation*Quaternion.Inverse(mountRotation);Vector3 rightTarget=rh.TransformPoint(rg)-handRotation*Vector3.Scale(rg,rh.lossyScale);if(weight>0){Quaternion lr=handRotation*Quaternion.Inverse(rb)*lb;Vector3 offset=handRotation*Vector3.Scale(rg,rh.lossyScale)-desiredRotation*Vector3.forward*.16f-lr*Vector3.Scale(lg,lh.lossyScale);float rr=Vector3.Distance(ru.position,rl.position)+Vector3.Distance(rl.position,rh.position)-.002f;float reach=Vector3.Distance(lu.position,ll.position)+Vector3.Distance(ll.position,lh.position)-.002f;Vector3 adjusted=rightTarget;for(int it=0;it<40;it++){adjusted=lu.position-offset+Vector3.ClampMagnitude(adjusted-(lu.position-offset),reach);adjusted=ru.position+Vector3.ClampMagnitude(adjusted-ru.position,rr);}rightTarget=Vector3.Lerp(rightTarget,adjusted,weight);}IK(ru,rl,rh,rightTarget);rh.rotation=handRotation;sword.localPosition=mountPosition;sword.localRotation=mountRotation;
     maxPositionShift=Mathf.Max(maxPositionShift,Vector3.Distance(originalSwordPosition,sword.position));
     if(weight>0){Quaternion leftTargetRotation=handRotation*Quaternion.Inverse(rb)*lb;Vector3 center=rh.TransformPoint(rg)-sword.forward*.16f;Vector3 leftTarget=center-leftTargetRotation*Vector3.Scale(lg,lh.lossyScale);IK(lu,ll,lh,leftTarget);var solvedUpper=lu.localRotation;var solvedLower=ll.localRotation;lu.localRotation=Quaternion.Slerp(leftUpper,solvedUpper,weight);ll.localRotation=Quaternion.Slerp(leftLower,solvedLower,weight);lh.rotation=Quaternion.Slerp(leftRot,leftTargetRotation,weight);if(weight>.999f){held++;maxLeftError=Mathf.Max(maxLeftError,Vector3.Distance(center,lh.TransformPoint(lg)));}}
     }foreach(var t in changed){var k=records[t];var p=t.localPosition;var q=t.localRotation;for(int c=0;c<7;c++)k[c].Add(new Keyframe(time,c<3?p[c]:q[c-3]));}
    }
    Undo.RecordObject(clip,"Fit hands to authored sword");if(!changed.Contains(lh))foreach(var t in new[]{lu,ll,lh}){string untouched=AnimationUtility.CalculateTransformPath(t,a.transform);foreach(var b in AnimationUtility.GetCurveBindings(source).Where(b=>b.path==untouched))AnimationUtility.SetEditorCurve(clip,b,AnimationUtility.GetEditorCurve(source,b));}foreach(var t in changed){string bpath=AnimationUtility.CalculateTransformPath(t,a.transform);foreach(var b in AnimationUtility.GetCurveBindings(clip).Where(b=>b.path==bpath&&(b.propertyName.Contains("Rotation")||b.propertyName.Contains("Euler")||b.propertyName.Contains("Position"))).ToArray())AnimationUtility.SetEditorCurve(clip,b,null);if(t==sword){for(int channel=0;channel<3;channel++){AnimationUtility.SetEditorCurve(clip,EditorCurveBinding.FloatCurve(bpath,typeof(Transform),"m_LocalPosition."+"xyz"[channel]),AnimationCurve.Linear(0,mountPosition[channel],source.length,mountPosition[channel]));AnimationUtility.SetEditorCurve(clip,EditorCurveBinding.FloatCurve(bpath,typeof(Transform),"localEulerAnglesRaw."+"xyz"[channel]),AnimationCurve.Linear(0,mountRotation.eulerAngles[channel],source.length,mountRotation.eulerAngles[channel]));}continue;}for(int c=0;c<7;c++){var curve=new AnimationCurve(records[t][c].ToArray());for(int k=0;k<curve.length;k++){AnimationUtility.SetKeyLeftTangentMode(curve,k,AnimationUtility.TangentMode.Linear);AnimationUtility.SetKeyRightTangentMode(curve,k,AnimationUtility.TangentMode.Linear);}AnimationUtility.SetEditorCurve(clip,EditorCurveBinding.FloatCurve(bpath,typeof(Transform),c<3?"m_LocalPosition."+"xyz"[c]:"m_LocalRotation."+"xyzw"[c-3]),curve);}}
    clip.EnsureQuaternionContinuity();float maxAngle=0;for(int f=0;f<=frames;f++){clip.SampleAnimation(a.gameObject,clip.length*f/frames);maxAngle=Mathf.Max(maxAngle,Quaternion.Angle(sword.rotation,desired[f]));}
    Undo.RecordObject(liveA.GetComponentInChildren<SkinnedMeshRenderer>(),"Close left fist");liveA.GetComponentInChildren<SkinnedMeshRenderer>().sharedMesh=fist;clip.SampleAnimation(liveA.gameObject,0);EditorUtility.SetDirty(clip);reports.Add(new{name=liveA.transform.parent.name,maxSwordAngleError=maxAngle,maxSwordPositionShift=maxPositionShift,maxLeftGripError=maxLeftError,twoHandSamples=held,totalSamples=frames+1});
   }finally{UnityEngine.Object.DestroyImmediate(root);}
  }
  AssetDatabase.SaveAssets();var scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);System.IO.File.WriteAllText("Assets/3DBattle/Authoring~/Attack01TailFitReport.json",Newtonsoft.Json.JsonConvert.SerializeObject(reports,Newtonsoft.Json.Formatting.Indented));return reports;
 }
